import { Transport } from "./transport.js";
import { ChatService } from "./chat.js";
import { ModelsService } from "./models.js";
import { ImageService } from "./image.js";
import { AudioService } from "./audio.js";
import { RealtimeService } from "./realtime.js";
import { VideoService } from "./video.js";
import { FilesService } from "./files.js";
import { EmbeddingsService } from "./embeddings.js";
import { Agent } from "./agent/agent.js";
import type { AgentOptions } from "./agent/types.js";
import { Workspace, type WorkspaceOptions } from "./agent/workspace.js";
import { AssetsService } from "./assets.js";
import { AppsService } from "./apps.js";
import { BrowserAuth, type BrowserUser } from "./browser-auth.js";
import { FilesRemote, SyncEngine, type SyncOptions, type SyncState } from "./sync/index.js";
import { SDKEvents } from "./events.js";

// The platform, not the bare gateway: personal rk_ keys are checked and
// billed by www.runapps.ai, which forwards to the gateway. api.runapps.ai
// only knows the gateway's own keys.
const DEFAULT_BASE_URL = "https://www.runapps.ai";

/**
 * Auth strategy.
 *
 *   - `"static"` (default): use `apiKey` or `apiKeyResolver` directly.
 *   - `"runapps"`: opt into the built-in browser auth flow that
 *     handshakes with `https://www.runapps.ai/api/sdk/grant`.  No
 *     external auth.js script needed; the SDK consumes the URL
 *     fragment after the redirect-back, exposes `client.user` and
 *     `client.signIn()`, and renders an identity badge.  Only useful
 *     in browsers — in Node this falls back to throwing the same
 *     "missing apiKey" error you'd get with no auth config.
 */
// "runapps" turns on the platform sign-in. "runjobs" is a deprecated
// alias for it, kept so code written before the rename keeps working.
export type AuthProvider = "static" | "runapps" | "runjobs";

export interface ClientOptions {
  /** A personal API key (`rk_…`) or another static key. Leave it out in an
   *  app published on RunApps: the browser client then signs the user in. */
  apiKey?: string;
  /**
   * Dynamic API key resolver.  See `AuthProvider` for the typical
   * runapps.ai browser-bundle wiring.
   *
   * Wins over `apiKey` when both are supplied.
   */
  apiKeyResolver?: () => string | Promise<string>;
  /**
   * Auth strategy. Rarely needed: in a browser with no `apiKey` /
   * `apiKeyResolver` the client uses `"runapps"` (the platform sign-in),
   * otherwise `"static"` (the key you pass).
   */
  authProvider?: AuthProvider;
  /**
   * Show the floating identity badge in `runapps` auth mode.
   * **Default `true`** — the badge is now a desktop-ball-style
   * real-time activity indicator (LED dot + progress ring around
   * the avatar + click-through popover with active calls / recent
   * completions / session totals). Set `false` only when the
   * bundle ships its own status UI and you don't want the platform
   * badge in the corner.
   */
  showIdentityBadge?: boolean;
  /**
   * How the browser auth flow obtains a token when there is none:
   * `"redirect"` (default) navigates the page away and back, losing
   * unsaved state; `"popup"` signs in through a popup window and
   * resumes the pending call, so the page keeps its state. See
   * `BrowserAuthOptions.signInMode`.
   */
  signInMode?: "redirect" | "popup";
  /**
   * Which corner the identity badge floats in. Defaults to
   * `"bottom-right"` — the canonical tray-app position. Switch to
   * `"bottom-left"` when the bundle's own UI occupies the right
   * gutter (e.g. a chat dock); the top corners are useful for
   * fullscreen / portrait kiosk layouts.
   *
   * The popover anchors itself to the same corner — bottom-left
   * badge → popover opens up + right of the badge; top-* badges →
   * popover opens down. Each corner only nudges the CSS; the badge
   * + popover content is identical.
   */
  badgePosition?: "bottom-right" | "bottom-left" | "top-right" | "top-left";
  /**
   * @deprecated Use `showIdentityBadge` instead.  Kept for back-compat;
   * acts as `showIdentityBadge: !hideIdentityBadge` when set.
   */
  hideIdentityBadge?: boolean;
  /**
   * Pin the runapps.ai grant flow to a specific project (only used
   * when `authProvider: "runapps"`).  When set, `/api/sdk/grant`
   * receives `project_id=<value>` and mints an `rrt_*` resource
   * token bound to THAT project — required for `client.files.*`
   * calls from any origin that isn't a registered (origin, app)
   * pair (e.g. a bundle running on `localhost:5173` during dev).
   *
   * Production bundles served from a registered origin can omit
   * this; the gateway derives the project from the (origin, app)
   * pair.
   */
  project?: string;
  /**
   * Where file calls go. By default the SDK asks the gateway for a
   * per-user base on the files host (`https://files.runapps.ai/u/<hash>`)
   * and falls back to the classic `/v1/files` paths on older gateways.
   * `false` keeps the classic paths; a URL overrides the base.
   */
  filesBase?: string | false;
  /** Override the default base URL, `https://www.runapps.ai` (the
   *  platform: personal keys and app tokens are both accepted there). */
  baseURL?: string;
  /** Optional fetch override (e.g. node-fetch with custom agent). */
  fetch?: typeof fetch;
  /**
   * RunApps Sync: keep the data the app stores in IndexedDB on every
   * device the user signs in on. **On by default** in an app on RunApps
   * (browser sign-in mode): the SDK observes every database the app
   * opens, pushes committed writes a few seconds later, pulls other
   * devices' changes when the page is opened, focused or comes back
   * online, and shows the state on the badge. Pass `false` to turn it
   * off, or options to limit it to some databases / leave stores out.
   * See `client.sync`.
   */
  sync?: boolean | SyncOptions;
}

/**
 * Top-level RunApps SDK client.  Construct once, share across services.
 *
 * Browser bundle (resource projects on runapps.ai):
 *
 * ```html
 * <script src="https://cdn.jsdelivr.net/npm/@runappsai/sdk/dist/sdk.umd.js"></script>
 * <script>
 *   const client = new RunApps();
 *   const res = await client.chat.create({
 *     model: "gpt-4o-mini",
 *     messages: [{ role: "user", content: "hello" }],
 *   });
 * </script>
 * ```
 *
 * Node / server-side:
 *
 * ```ts
 * import { RunApps } from "@runappsai/sdk";
 * const client = new RunApps({ apiKey: process.env.RUNAPPS_API_KEY! });
 * ```
 */
export class RunApps {
  readonly chat: ChatService;
  readonly models: ModelsService;
  readonly image: ImageService;
  readonly audio: AudioService;
  readonly video: VideoService;
  readonly files: FilesService;
  readonly embeddings: EmbeddingsService;
  /** Realtime voice sessions over WebSocket — see `RealtimeService.connect`. */
  readonly realtime: RealtimeService;
  /** Seedance asset verification (a gated feature) — see `AssetsService`. */
  readonly assets: AssetsService;
  /** App handoff: send files to another app and receive what other apps
   *  send this one — see `AppsService`. */
  readonly apps: AppsService;
  private readonly transport: Transport;
  /** The `project` option, when given (scopes workspaces). */
  private readonly projectName: string | undefined;

  /**
   * Browser auth helper, populated only when `authProvider: "runapps"`.
   * Use `client.signIn()` and `client.user` for the common cases; the
   * full instance is exposed for advanced flows (manual `onTokenChange`
   * subscription, etc.).
   */
  readonly auth: BrowserAuth | null = null;
  /**
   * RunApps Sync (see `ClientOptions.sync`), or null when it
   * is off. `status()` gives the state the badge shows; `now()` pushes
   * and pulls immediately; `client.events.on("db:change", …)` tells the
   * app which store received remote changes so it can re-read.
   */
  readonly sync: { status(): SyncState; now(): Promise<void>; pause(): void; resume(): void; dispose(): void } | null = null;

  /**
   * Runtime event bus for SDK-call telemetry. Every LLM-ish service
   * (chat / embeddings / image / audio / video) fires
   * `request:start`, `request:streamDelta`, `request:end`, and
   * `request:error` events here so UI overlays — like the bottom-right
   * identity badge's activity ring — can render real-time state
   * without business code threading anything through.
   *
   * Zero-cost when nobody subscribes (emit is a few property reads).
   * Subscribe via `client.events.on("request:start", handler)` — the
   * returned closure is the unsubscribe.
   */
  readonly events: SDKEvents = new SDKEvents();

  constructor(options: ClientOptions = {}) {
    // With no key and no explicit authProvider, a browser client uses the
    // platform sign-in: `new RunApps()` is all an app needs. Elsewhere
    // (Node, workers without a window) there is no one to sign in.
    const provider =
      options.authProvider ??
      (!options.apiKey && !options.apiKeyResolver && typeof window !== "undefined"
        ? "runapps"
        : "static");
    let apiKeyResolver = options.apiKeyResolver;
    let baseURL = options.baseURL;
    let onUnauthorized: (() => void) | undefined;

    if (provider === "runapps" || provider === "runjobs") {
      // The grant page (/api/sdk/grant) and the gateway both live on
      // www.runapps.ai.  An explicit baseURL keeps control.
      baseURL = baseURL ?? "https://www.runapps.ai";
      // Badge default: SHOWN. The badge is now a real-time activity
      // indicator (LED + ring + popover) — useful enough that we'd
      // rather have the rare "I already have my own UI" bundle opt
      // OUT with `showIdentityBadge: false` than have every bundle
      // miss the live feedback by default. The legacy
      // `hideIdentityBadge` flag still wins when set, for callers
      // that explicitly suppressed the badge under the old default.
      const showBadge =
        options.showIdentityBadge !== undefined
          ? options.showIdentityBadge
          : options.hideIdentityBadge !== undefined
            ? !options.hideIdentityBadge
            : true;
      const auth = new BrowserAuth({
        origin: baseURL,
        hideBadge: !showBadge,
        // Pipe the shared event bus into BrowserAuth so the badge can
        // render its real-time activity ring / LED / popover. Safe to
        // pass even when the caller never subscribes — emit is a few
        // property reads when nobody's listening.
        events: this.events,
        ...(options.badgePosition !== undefined && { badgePosition: options.badgePosition }),
        ...(options.project !== undefined && { project: options.project }),
        ...(options.signInMode !== undefined && { signInMode: options.signInMode }),
      });
      (this as { auth: BrowserAuth | null }).auth = auth;
      // The browser auth resolver wins over any caller-supplied one
      // because the auth flow owns token issuance + refresh from now on.
      apiKeyResolver = auth.getToken;
      // 401 from the gateway → token was revoked server-side (typically
      // because the user unsubscribed in another tab).  Drop the cached
      // token so the transport's auto-retry hits a fresh signIn() flow.
      onUnauthorized = () => auth.invalidate();
    }

    if (!options.apiKey && !apiKeyResolver) {
      throw new Error(
        "runapps: pass `apiKey` (or `apiKeyResolver`); outside a browser there is no sign-in to fall back to",
      );
    }
    const transport = new Transport({
      baseURL: baseURL ?? DEFAULT_BASE_URL,
      ...(options.apiKey !== undefined && { apiKey: options.apiKey }),
      ...(apiKeyResolver !== undefined && { apiKeyResolver }),
      ...(onUnauthorized !== undefined && { onUnauthorized }),
      ...(options.fetch ? { fetchImpl: options.fetch } : {}),
    });
    // Service constructors receive the shared event bus so each call
    // path (chat/embeddings/image/audio/video) can emit
    // start/end/error around its network operations. Files and Models
    // intentionally don't take it — they're infrastructure, not
    // user-facing LLM calls, and surfacing them would clutter the
    // badge with /v1/models polls.
    this.chat = new ChatService(transport, this.events);
    this.models = new ModelsService(transport);
    this.image = new ImageService(transport, this.events);
    this.audio = new AudioService(transport, this.events);
    this.video = new VideoService(transport, this.events);
    // `project` also scopes the file URLs (/v1/p/<project>/files/...),
    // so two apps never issue byte-identical file requests.  Omitted →
    // legacy unscoped /v1/files/... paths.
    this.projectName = options.project;
    this.files = new FilesService(transport, options.project, this.events, options.filesBase);
    this.embeddings = new EmbeddingsService(transport, this.events);
    this.realtime = new RealtimeService(transport, this.events);
    this.assets = new AssetsService(transport);
    this.apps = new AppsService(
      transport,
      this.files,
      options.project,
      () => !!options.apiKey || !!options.apiKeyResolver || !!this.auth?.user,
    );
    this.transport = transport;

    // Sync: an app on RunApps gets it unless it says no. It
    // stores under the signed-in user, so only browser sign-in mode has
    // someone to sync for.
    const wantSync = options.sync ?? this.auth !== null;
    if (wantSync && typeof indexedDB !== "undefined" && this.auth) {
      const auth = this.auth;
      const engine = new SyncEngine(
        {
          // Its own file service, without the event bus: sync traffic
          // must not spin the badge every minute.
          remote: new FilesRemote(new FilesService(transport, options.project, undefined, options.filesBase)),
          events: this.events,
          userId: () => auth.ownerId(),
          onAuthChange: (cb) => auth.onTokenChange(() => cb()),
        },
        typeof wantSync === "object" ? wantSync : {},
      );
      (this as { sync: RunApps["sync"] }).sync = engine;
    }
  }

  /** Force a redirect to the runapps.ai grant page.  No-op in static
   *  auth mode or in Node. */
  signIn(): Promise<void> | void {
    return this.auth?.signIn();
  }

  /**
   * Clear the cached token + identity from memory and localStorage.
   * The next API call will trigger sign-in again (redirect to grant
   * page).  Wire this to a "Sign out" button in your settings UI.
   *
   * No-op in static auth mode or in Node.
   */
  signOut(): void {
    this.auth?.signOut();
  }

  /**
   * The caller as the platform sees them, with the gated features the
   * platform enabled for them (e.g. "seedance_asset_verify"), so an app
   * shows a gated control only to those who have it.
   */
  /**
   * An agent: the model ↔ tool loop with your tools, a workspace of
   * files and skills, and your dialogs. See the README section "Agents".
   */
  agent(opts: AgentOptions = {}): Agent {
    return new Agent(this, opts);
  }

  /**
   * A workspace for agents: a file tree in IndexedDB with skills unpacked
   * from zip(s). Resolves once the skills are in place.
   */
  workspace(opts: WorkspaceOptions = {}): Promise<Workspace> {
    return Workspace.open(this, { project: this.projectName, ...opts });
  }

  me(init?: { signal?: AbortSignal }): Promise<Me> {
    return this.transport.getJSON<Me>("/v1/me", init);
  }

  /** Currently-authenticated user (runapps auth mode), or null. */
  get user(): BrowserUser | null {
    return this.auth?.user ?? null;
  }
}

/** `client.me()`: the signed-in user and their gated features. */
export interface Me {
  id: string;
  name: string;
  /** Feature names the platform enabled for this user. */
  features: string[];
}
